import tailwindcss from '@tailwindcss/vite';
import { brandingPlugin, loadBrandingConfig } from 'desy-html/branding/plugin';
import fs from 'fs';
import { glob } from 'glob';
import hljs from 'highlight.js';
import beautify from 'js-beautify';
import yaml from 'js-yaml';
import nunjucks from 'nunjucks';
import { outdent } from 'outdent';
import path from 'path';
import sharp from 'sharp';
import { defineConfig } from 'vite';

// Load branding configuration
const brandingConfig = await loadBrandingConfig(
  process.env.BRANDING_CONFIG || 'default',
  process.cwd(),
  'branding'
);
if (brandingConfig) {
  console.log('✓ Branding loaded from configuration');
}

function kebabCaseToPascalCase(value) {
  return value
    .toLowerCase()
    .split('-')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join('');
}

function getBeautifyOptions() {
  const options = beautify.html.defaultOptions();
  return {
    indent_size: 2,
    inline: options.inline.filter((tag) => !['label'].includes(tag)),
    max_preserve_newlines: 0,
    wrap_attributes: 'preserve'
  };
}

function setupNunjucksEnvironment(paths, options = {}) {
  const defaultOptions = {
    autoescape: true,
    trimBlocks: true,
    lstripBlocks: true,
    throwOnUndefined: false,
    noCache: true
  };

  const env = nunjucks.configure(paths, { ...defaultOptions, ...options });
  env.addGlobal('assetsUrl', '/src');
  env.addGlobal('branding', brandingConfig);

  env.addGlobal('loadComponentParams', function (componentName) {
    try {
      const yamlPath = path.join(process.cwd(), 'src/templates/components', componentName, `params.${componentName}.yaml`);

      if (fs.existsSync(yamlPath)) {
        const content = fs.readFileSync(yamlPath, 'utf8');
        const parsedYaml = yaml.load(content);
        const dumpedYaml = yaml.dump(parsedYaml);
        return dumpedYaml;
      }
      console.error(`YAML file not found: ${yamlPath}`);
      return '';
    } catch (err) {
      console.error(`Error loading YAML for ${componentName}:`, err);
      return '';
    }
  });

  env.addGlobal('getHTMLCodeFromExample', function (componentName, params, pathName) {
    const templatePath = `${pathName}s/${componentName}/_template.${componentName}.njk`;
    const html = env.render(templatePath, { params }).trim();
    return beautify.html(html, getBeautifyOptions());
  });

  env.addGlobal('getHTMLCodeFromFile', function (templatePath) {
    const html = env.render(templatePath).trim();
    return beautify.html(html, getBeautifyOptions());
  });

  env.addGlobal('getNunjucksCodeFromExample', function (componentName, params, pathName) {
    const macroName = kebabCaseToPascalCase(componentName);
    return outdent`
      {% from "${pathName}s/${componentName}/_macro.${componentName}.njk" import ${pathName}${macroName} %}
      {{ ${pathName}${macroName}(${JSON.stringify(params, undefined, 2)
      }) }}
    `;
  });

  env.addGlobal('getNunjucksCodeFromFile', function (templatePath) {
    try {
      const codeFromFile = fs.readFileSync(
        path.join(process.cwd(), 'src/templates', templatePath),
        'utf8'
      );
      return outdent`
        ${codeFromFile}
      `;
    } catch (err) {
      console.error(`Error reading file ${templatePath}:`, err);
      return '';
    }
  });

  env.addFilter('filtercaller', function (params) {
    if (params && typeof params === 'object') {
      const filteredParams = { ...params };
      delete filteredParams.caller;
      return filteredParams;
    }
    return params;
  });

  env.addFilter('filterslugify', function (str) {
    if (typeof str !== 'string') return '';
    let slug = str.replace(/\s+/g, '-');
    slug = slug.replace(/[^\w-]+/g, '');
    slug = slug.toLowerCase();
    return slug;
  });

  env.addFilter('highlight', function (code, language) {
    try {
      return hljs.highlight(code.trim(), {
        language: language || 'plaintext'
      }).value;
    } catch (err) {
      console.error('Error highlighting code:', err);
      return code;
    }
  });

  env.addFilter('filterescapeltgt', function (str) {
    if (typeof str !== 'string' && typeof str !== 'object') return str;
    if (typeof str !== 'string') str = JSON.stringify(str);
    return str.replace(/</g, '&lt;').replace(/>/g, '&gt;');
  });

  env.addFilter('filterquotes', function (str) {
    if (typeof str !== 'string') return str;
    let inTag = false;
    let result = '';
    let currentQuote = null;
    for (let i = 0; i < str.length; i++) {
      const char = str[i];
      if (char === '<') {
        inTag = true;
        result += char;
        continue;
      }
      if (char === '>') {
        inTag = false;
        result += char;
        continue;
      }
      if (inTag) {
        if (char === "'" || char === '"') {
          if (currentQuote === null) {
            currentQuote = char;
            result += '"';
          } else if (currentQuote === char) {
            currentQuote = null;
            result += '"';
          } else {
            result += char;
          }
        } else {
          result += char;
        }
      } else {
        result += char;
      }
    }
    return result;
  });

  env.addFilter('filterversion', function () {
    const pkg = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'package.json'), 'utf8'));
    return pkg.version;
  });

  return env;
}

async function processNunjucksFiles(env) {
  try {
    const srcPath = path.resolve(process.cwd(), 'src');
    const htmlFiles = await glob('*.html', { cwd: srcPath });

    for (const htmlFile of htmlFiles) {
      try {
        const sourcePath = path.join(srcPath, htmlFile);
        const outputPath = path.join(process.cwd(), 'dist', htmlFile);

        const content = await fs.promises.readFile(sourcePath, 'utf8');
        let processedHtml = env.renderString(content);

        processedHtml = processedHtml.replace(/href=["']\/src\/css\/([^"']*)["']/g, 'href="css/$1"');
        processedHtml = processedHtml.replace(/href=["']src\/css\/([^"']*)["']/g, 'href="css/$1"');

        processedHtml = processedHtml.replace(/src=["']\/src\/js\/([^"']*)["']/g, 'src="js/$1"');
        processedHtml = processedHtml.replace(/src=["']src\/js\/([^"']*)["']/g, 'src="js/$1"');
        processedHtml = processedHtml.replace(/src=["']\/js\/([^"']*)["']/g, 'src="js/$1"');

        processedHtml = processedHtml.replace(/src=["']\/images\/([^"']*)["']/g, 'src="images/$1"');
        processedHtml = processedHtml.replace(/src=["']images\/([^"']*)["']/g, 'src="images/$1"');

        await fs.promises.mkdir(path.dirname(outputPath), { recursive: true });
        await fs.promises.writeFile(outputPath, processedHtml);
      } catch (fileError) {
        console.error(`Error processing file ${htmlFile}:`, fileError);
      }
    }
  } catch (error) {
    console.error('Error in processNunjucksFiles:', error);
  }
}

async function optimizeImage(sourcePath, destPath, fileExtension) {
  try {
    const image = sharp(sourcePath);

    switch (fileExtension.toLowerCase()) {
      case '.jpg':
      case '.jpeg':
        await image
          .jpeg({
            quality: 80,
            mozjpeg: true,
            progressive: true
          })
          .toFile(destPath);
        break;

      case '.png':
        await image
          .png({
            quality: 80,
            palette: true,
            compressionLevel: 9
          })
          .toFile(destPath);
        break;

      case '.webp':
        await image
          .webp({
            quality: 80,
            effort: 6
          })
          .toFile(destPath);
        break;

      case '.avif':
        await image
          .avif({
            quality: 80,
            effort: 4
          })
          .toFile(destPath);
        break;

      case '.svg':
        await fs.promises.copyFile(sourcePath, destPath);
        break;

      default:
        await fs.promises.copyFile(sourcePath, destPath);
        break;
    }

    return true;
  } catch (error) {
    console.error(`❌ Error optimizing ${sourcePath}:`, error.message);
    try {
      await fs.promises.copyFile(sourcePath, destPath);
      return true;
    } catch (copyError) {
      console.error(`❌ Error copying ${sourcePath}:`, copyError.message);
      return false;
    }
  }
}

async function copyAndOptimizeImages() {
  try {
    const desyImagesDir = path.resolve(process.cwd(), 'node_modules/desy-html/public/images');
    const projectImagesDir = path.resolve(process.cwd(), 'public/images');
    const distImagesDir = path.resolve(process.cwd(), 'dist/images');

    await fs.promises.mkdir(distImagesDir, { recursive: true });

    const imageSources = [
      { dir: desyImagesDir, name: 'desy-html', priority: 1 },
      { dir: projectImagesDir, name: 'project', priority: 2 }
    ];

    let optimizedCount = 0;
    let copiedCount = 0;
    let totalSizeBefore = 0;
    let totalSizeAfter = 0;
    const processedFiles = new Map();

    for (const source of imageSources) {
      if (!fs.existsSync(source.dir)) {
        console.log(`📁 ${source.name} images directory does not exist, skipping...`);
        continue;
      }

      const imageFiles = await glob('**/*.{png,jpg,jpeg,gif,svg,webp,avif,ico,bmp,tiff}', {
        cwd: source.dir,
        nodir: true
      });

      console.log(`🖼️  Processing ${imageFiles.length} images from ${source.name}...`);

      for (const imageFile of imageFiles) {
        const sourcePath = path.join(source.dir, imageFile);
        const destPath = path.join(distImagesDir, imageFile);
        const fileExtension = path.extname(imageFile);

        if (processedFiles.has(imageFile) && source.priority <= processedFiles.get(imageFile).priority) {
          continue;
        }

        await fs.promises.mkdir(path.dirname(destPath), { recursive: true });

        const statsBefore = await fs.promises.stat(sourcePath);
        totalSizeBefore += statsBefore.size;

        const success = await optimizeImage(sourcePath, destPath, fileExtension);

        if (success) {
          if (fs.existsSync(destPath)) {
            const statsAfter = await fs.promises.stat(destPath);
            totalSizeAfter += statsAfter.size;

            const reduction = ((statsBefore.size - statsAfter.size) / statsBefore.size * 100).toFixed(1);
            const isOverride = processedFiles.has(imageFile);

            if (['.jpg', '.jpeg', '.png', '.webp', '.avif'].includes(fileExtension.toLowerCase())) {
              console.log(`✨ ${isOverride ? 'Override' : 'Optimized'}: ${imageFile} from ${source.name} (${reduction}% reduced)`);
              optimizedCount++;
            } else {
              console.log(`📄 ${isOverride ? 'Override' : 'Copied'}: ${imageFile} from ${source.name}`);
              copiedCount++;
            }

            processedFiles.set(imageFile, { source: source.name, priority: source.priority });
          }
        }
      }
    }

    const totalReduction = totalSizeBefore > 0 ? ((totalSizeBefore - totalSizeAfter) / totalSizeBefore * 100).toFixed(1) : 0;
    const sizeBefore = (totalSizeBefore / 1024).toFixed(1);
    const sizeAfter = (totalSizeAfter / 1024).toFixed(1);

    console.log(`🎉 Image processing completed:`);
    console.log(`   ✨ ${optimizedCount} images optimized`);
    console.log(`   📄 ${copiedCount} files copied`);
    console.log(`   📊 Size: ${sizeBefore}KB → ${sizeAfter}KB (${totalReduction}% reduced)`);
    console.log(`   📦 Sources: desy-html (base) + project (overrides)`);

  } catch (error) {
    console.error('❌ Error in copyAndOptimizeImages:', error);
  }
}

async function copyJsLibraries() {
  try {
    const distJsDir = path.resolve(process.cwd(), 'dist/js');
    await fs.promises.mkdir(distJsDir, { recursive: true });

    const jsLibraries = ['headroom.min.js'];

    for (const jsFile of jsLibraries) {
      const srcPath = path.resolve(process.cwd(), 'src/js', jsFile);
      const desyPath = path.resolve(process.cwd(), 'node_modules/desy-html/src/js', jsFile);
      const destPath = path.join(distJsDir, jsFile);

      if (fs.existsSync(srcPath)) {
        await fs.promises.copyFile(srcPath, destPath);
        console.log(`📄 Copied JS library: ${jsFile} from src/js`);
      } else if (fs.existsSync(desyPath)) {
        await fs.promises.copyFile(desyPath, destPath);
        console.log(`📄 Copied JS library: ${jsFile} from desy-html`);
      } else {
        console.warn(`⚠️ JS library not found: ${jsFile}`);
      }
    }
  } catch (error) {
    console.error('Error copying JS libraries:', error);
  }
}

