async function validateBuild() {
  try {
    const distPath = path.resolve(process.cwd(), 'dist');

    const htmlFiles = await glob('**/*.html', { cwd: distPath });

    for (const htmlFile of htmlFiles) {
      const filePath = path.join(distPath, htmlFile);
      const content = await fs.promises.readFile(filePath, 'utf8');

      if (content.includes('/src/') || content.includes('src/')) {
        let correctedContent = content
          .replace(/href=["']\/src\/([^"']*)["']/g, 'href="$1"')
          .replace(/href=["']src\/([^"']*)["']/g, 'href="$1"')
          .replace(/src=["']\/src\/([^"']*)["']/g, 'src="$1"')
          .replace(/src=["']src\/([^"']*)["']/g, 'src="$1"');

        await fs.promises.writeFile(filePath, correctedContent);
      }
    }

    for (const htmlFile of htmlFiles) {
      const filePath = path.join(distPath, htmlFile);
      const content = await fs.promises.readFile(filePath, 'utf8');

      const hasAbsoluteScripts = /<script[^>]*src=["']\/[^"']*["'][^>]*>/g.test(content);

      if (hasAbsoluteScripts) {
        let correctedContent = content.replace(
          /<script([^>]*)src=["']\/([^"']*)["']([^>]*)>/g,
          '<script$1src="$2"$3>'
        );

        await fs.promises.writeFile(filePath, correctedContent);
      }
    }

    const jsFiles = await glob('js/**/*.js', { cwd: distPath });

    for (const jsFile of jsFiles) {
      const filePath = path.join(distPath, jsFile);
      const content = await fs.promises.readFile(filePath, 'utf8');

      if (content.includes('.css"') || content.includes(".css'")) {
        let correctedContent = content.replace(
          /import\s+['"](.+\.css)['"];?/g,
          '// CSS import removed: $1'
        );

        await fs.promises.writeFile(filePath, correctedContent);
      }
    }

  } catch (error) {
    console.error('Error validating build:', error);
  }
}

async function rewriteCssImagePaths() {
  const stylePath = path.resolve(process.cwd(), 'dist/css/styles.css');
  if (!fs.existsSync(stylePath)) return;
  let content = await fs.promises.readFile(stylePath, 'utf8');
  content = content.replace(/url\((['"]?)\/images\//g, 'url($1../images/');
  await fs.promises.writeFile(stylePath, content);
}

async function rewriteHtmlImagePaths() {
  const distDir = path.resolve(process.cwd(), 'dist');
  if (!fs.existsSync(distDir)) return;

  const htmlFiles = await glob('**/*.html', { cwd: distDir, nodir: true });

  for (const htmlFile of htmlFiles) {
    const filePath = path.join(distDir, htmlFile);
    let content = await fs.promises.readFile(filePath, 'utf8');

    let modified = content
      .replace(/src="(\/branding\/logos\/)/g, 'src="./images/')
      .replace(/srcset="(\/branding\/logos\/)/g, 'srcset="./images/')
      .replace(/src="(\/branding\/images\/)/g, 'src="./images/')
      .replace(/href="(\/branding\/logos\/)/g, 'href="./images/')
      .replace(/href="(\/branding\/images\/)/g, 'href="./images/');

    if (modified !== content) {
      await fs.promises.writeFile(filePath, modified);
    }
  }
}

async function copyBrandingAssets() {
  try {
    const brandingDir = path.resolve(process.cwd(), 'branding');
    const desyBrandingDir = path.resolve(process.cwd(), 'node_modules/desy-html/branding');
    const distImagesDir = path.resolve(process.cwd(), 'dist/images');

    // Use local branding if exists, otherwise fallback to desy-html node_modules
    const sourceBrandingDir = fs.existsSync(brandingDir) ? brandingDir : desyBrandingDir;

    if (!fs.existsSync(sourceBrandingDir)) {
      console.log('📁 No branding assets found');
      return;
    }

    if (!fs.existsSync(brandingDir)) {
      console.log('📁 branding/ not found, using desy-html defaults');
    }

    await fs.promises.mkdir(distImagesDir, { recursive: true });

    // Helper to copy files from a directory
    async function copyFromDir(sourceDir, subDir) {
      const fullSourceDir = path.join(sourceDir, subDir);
      if (!fs.existsSync(fullSourceDir)) return;

      const files = await glob('**/*.{svg,png,jpg,jpeg}', { cwd: fullSourceDir, nodir: true });
      for (const file of files) {
        const sourcePath = path.join(fullSourceDir, file);
        const fileName = path.basename(file);
        const destPath = path.join(distImagesDir, fileName);
        await fs.promises.copyFile(sourcePath, destPath);
      }
    }

    // Copy logos
    await copyFromDir(sourceBrandingDir, 'logos');

    // Copy header background images
    await copyFromDir(sourceBrandingDir, 'images');

    console.log('✅ Branding assets copied to dist/images/');
  } catch (error) {
    console.error('❌ Error in copyBrandingAssets:', error.message);
  }
}

function customNunjucksPlugin() {
  let env;

  return {
    name: 'vite-plugin-custom-nunjucks',

    configureServer({ middlewares, watcher, ws }) {
      env = setupNunjucksEnvironment([
        'src', 
        'src/templates', 
        'node_modules/desy-html/src/templates'
      ], {
        watch: true,
        throwOnUndefined: false
      });

      watcher.add(['src/**/*.css', 'src/**/*.njk', 'node_modules/desy-html/src/**/*.njk']);
      watcher.on('change', () => {
        ws.send({ type: 'full-reload' });
      });

      middlewares.use(async (req, res, next) => {
        if (req.url.startsWith('/css/')) {
          req.url = req.url.replace('/css/', '/src/css/');
        }
        if (req.url.startsWith('/js/')) {
          const rawJsFileName = decodeURIComponent(req.url.slice(4).split('?')[0]);
          const normalizedJsFileName = path.posix.normalize(rawJsFileName);

          if (normalizedJsFileName.includes('..') || normalizedJsFileName.startsWith('/')) {
            res.statusCode = 404;
            return res.end('Not found');
          }

          const srcJsBase = path.resolve(process.cwd(), 'src/js');
          const desyJsBase = path.resolve(process.cwd(), 'node_modules/desy-html/src/js');
          const srcJsPath = path.join(srcJsBase, normalizedJsFileName);
          const desyJsPath = path.join(desyJsBase, normalizedJsFileName);

          if (!srcJsPath.startsWith(srcJsBase) || !desyJsPath.startsWith(desyJsBase)) {
            res.statusCode = 404;
            return res.end('Not found');
          }

          if (fs.existsSync(srcJsPath)) {
            req.url = req.url.replace('/js/', '/src/js/');
          } else if (fs.existsSync(desyJsPath)) {
            res.setHeader('Content-Type', 'application/javascript');
            res.setHeader('Cache-Control', 'no-cache');
            return fs.createReadStream(desyJsPath).pipe(res);
          }
        }
        if (req.url.endsWith('.js')) {
          res.setHeader('Content-Type', 'application/javascript');
        }
        next();
      });

      // Helper function to find file recursively in directories
      function findFileRecursive(dir, fileName) {
        if (!fs.existsSync(dir)) return null;
        const files = fs.readdirSync(dir);
        for (const file of files) {
          const fullPath = path.join(dir, file);
          if (fs.statSync(fullPath).isDirectory()) {
            const found = findFileRecursive(fullPath, fileName);
            if (found) return found;
          } else if (file === fileName) {
            return fullPath;
          }
        }
        return null;
      }

      // Middleware to serve branding assets from /branding/logos/ in development
      middlewares.use(async (req, res, next) => {
        if (req.url.startsWith('/branding/logos/')) {
          const fileName = path.basename(req.url);
          const brandingLogosPath = path.join(process.cwd(), 'branding/logos');
          const filePath = findFileRecursive(brandingLogosPath, fileName);

          if (!filePath) {
            // Fallback to desy-html node_modules
            const desyBrandingPath = path.join(process.cwd(), 'node_modules/desy-html/branding/logos');
            const desyFilePath = findFileRecursive(desyBrandingPath, fileName);
            if (desyFilePath && fs.existsSync(desyFilePath)) {
              const ext = path.extname(fileName).toLowerCase();
              const mimeTypes = {
                '.svg': 'image/svg+xml',
                '.png': 'image/png',
                '.jpg': 'image/jpeg',
                '.jpeg': 'image/jpeg',
                '.webp': 'image/webp'
              };
              res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
              return fs.createReadStream(desyFilePath).pipe(res);
            }
          }

          if (filePath && fs.existsSync(filePath)) {
            const ext = path.extname(fileName).toLowerCase();
            const mimeTypes = {
              '.svg': 'image/svg+xml',
              '.png': 'image/png',
              '.jpg': 'image/jpeg',
              '.jpeg': 'image/jpeg',
              '.webp': 'image/webp'
            };
            res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
            return fs.createReadStream(filePath).pipe(res);
          }
        }
        next();
      });

      // Middleware to serve branding assets from /branding/images/ in development
      middlewares.use(async (req, res, next) => {
        if (req.url.startsWith('/branding/images/')) {
          const fileName = path.basename(req.url);
          const brandingImagesPath = path.join(process.cwd(), 'branding/images');
          const filePath = findFileRecursive(brandingImagesPath, fileName);

          if (!filePath) {
            // Fallback to desy-html node_modules
            const desyBrandingPath = path.join(process.cwd(), 'node_modules/desy-html/branding/images');
            const desyFilePath = findFileRecursive(desyBrandingPath, fileName);
            if (desyFilePath && fs.existsSync(desyFilePath)) {
              const ext = path.extname(fileName).toLowerCase();
              const mimeTypes = {
                '.svg': 'image/svg+xml',
                '.png': 'image/png',
                '.jpg': 'image/jpeg',
                '.jpeg': 'image/jpeg',
                '.webp': 'image/webp'
              };
              res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
              return fs.createReadStream(desyFilePath).pipe(res);
            }
          }

          if (filePath && fs.existsSync(filePath)) {
            const ext = path.extname(fileName).toLowerCase();
            const mimeTypes = {
              '.svg': 'image/svg+xml',
              '.png': 'image/png',
              '.jpg': 'image/jpeg',
              '.jpeg': 'image/jpeg',
              '.webp': 'image/webp'
            };
            res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
            return fs.createReadStream(filePath).pipe(res);
          }
        }
        next();
      });

      // Middleware to serve /images/ in development (with branding fallback)
      middlewares.use(async (req, res, next) => {
        if (req.url.startsWith('/images/')) {
          const rawPath = decodeURIComponent(req.url.slice(8).split('?')[0]);
          const normalizedPath = path.posix.normalize(rawPath);

          if (normalizedPath.includes('..') || normalizedPath.startsWith('/')) {
            res.statusCode = 404;
            return res.end('Not found');
          }

          const projectImagesBase = path.resolve(process.cwd(), 'public/images');
          const projectImagePath = path.join(projectImagesBase, normalizedPath);

          // Check if image exists in public/images first
          if (projectImagePath.startsWith(projectImagesBase) && fs.existsSync(projectImagePath)) {
            const ext = path.extname(normalizedPath).toLowerCase();
            const mimeTypes = {
              '.svg': 'image/svg+xml',
              '.png': 'image/png',
              '.jpg': 'image/jpeg',
              '.jpeg': 'image/jpeg',
              '.gif': 'image/gif',
              '.webp': 'image/webp',
              '.avif': 'image/avif',
              '.ico': 'image/x-icon',
              '.bmp': 'image/bmp'
            };
            res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
            res.setHeader('Cache-Control', 'no-cache');
            return fs.createReadStream(projectImagePath).pipe(res);
          }

          // Search in branding/logos/ (recursive, including subdirectories like eu/)
          const brandingLogosPath = path.join(process.cwd(), 'branding/logos');
          const foundInLogos = findFileRecursive(brandingLogosPath, path.basename(normalizedPath));
          if (foundInLogos && fs.existsSync(foundInLogos)) {
            const ext = path.extname(normalizedPath).toLowerCase();
            const mimeTypes = {
              '.svg': 'image/svg+xml',
              '.png': 'image/png',
              '.jpg': 'image/jpeg',
              '.jpeg': 'image/jpeg',
              '.gif': 'image/gif',
              '.webp': 'image/webp',
              '.avif': 'image/avif',
              '.ico': 'image/x-icon',
              '.bmp': 'image/bmp'
            };
            res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
            res.setHeader('Cache-Control', 'no-cache');
            return fs.createReadStream(foundInLogos).pipe(res);
          }

          // Search in branding/images/
          const brandingImagesPath = path.join(process.cwd(), 'branding/images');
          const foundInImages = findFileRecursive(brandingImagesPath, path.basename(normalizedPath));
          if (foundInImages && fs.existsSync(foundInImages)) {
            const ext = path.extname(normalizedPath).toLowerCase();
            const mimeTypes = {
              '.svg': 'image/svg+xml',
              '.png': 'image/png',
              '.jpg': 'image/jpeg',
              '.jpeg': 'image/jpeg',
              '.gif': 'image/gif',
              '.webp': 'image/webp',
              '.avif': 'image/avif',
              '.ico': 'image/x-icon',
              '.bmp': 'image/bmp'
            };
            res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
            res.setHeader('Cache-Control', 'no-cache');
            return fs.createReadStream(foundInImages).pipe(res);
          }

          // Fallback to desy-html node_modules
          const desyImagesBase = path.resolve(process.cwd(), 'node_modules/desy-html/public/images');
          const desyImagePath = path.join(desyImagesBase, normalizedPath);

          if (fs.existsSync(desyImagePath)) {
            const ext = path.extname(normalizedPath).toLowerCase();
            const mimeTypes = {
              '.svg': 'image/svg+xml',
              '.png': 'image/png',
              '.jpg': 'image/jpeg',
              '.jpeg': 'image/jpeg',
              '.gif': 'image/gif',
              '.webp': 'image/webp',
              '.avif': 'image/avif',
              '.ico': 'image/x-icon',
              '.bmp': 'image/bmp'
            };
            res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
            res.setHeader('Cache-Control', 'no-cache');
            return fs.createReadStream(desyImagePath).pipe(res);
          }

          // Fallback to desy-html branding/logos (recursive)
          const desyBrandingLogosPath = path.join(process.cwd(), 'node_modules/desy-html/branding/logos');
          const foundInDesyLogos = findFileRecursive(desyBrandingLogosPath, path.basename(normalizedPath));
          if (foundInDesyLogos && fs.existsSync(foundInDesyLogos)) {
            const ext = path.extname(normalizedPath).toLowerCase();
            const mimeTypes = {
              '.svg': 'image/svg+xml',
              '.png': 'image/png',
              '.jpg': 'image/jpeg',
              '.jpeg': 'image/jpeg',
              '.gif': 'image/gif',
              '.webp': 'image/webp',
              '.avif': 'image/avif',
              '.ico': 'image/x-icon',
              '.bmp': 'image/bmp'
            };
            res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
            res.setHeader('Cache-Control', 'no-cache');
            return fs.createReadStream(foundInDesyLogos).pipe(res);
          }

          // Fallback to desy-html branding/images (recursive)
          const desyBrandingImagesPath = path.join(process.cwd(), 'node_modules/desy-html/branding/images');
          const foundInDesyImages = findFileRecursive(desyBrandingImagesPath, path.basename(normalizedPath));
          if (foundInDesyImages && fs.existsSync(foundInDesyImages)) {
            const ext = path.extname(normalizedPath).toLowerCase();
            const mimeTypes = {
              '.svg': 'image/svg+xml',
              '.png': 'image/png',
              '.jpg': 'image/jpeg',
              '.jpeg': 'image/jpeg',
              '.gif': 'image/gif',
              '.webp': 'image/webp',
              '.avif': 'image/avif',
              '.ico': 'image/x-icon',
              '.bmp': 'image/bmp'
            };
            res.setHeader('Content-Type', mimeTypes[ext] || 'application/octet-stream');
            res.setHeader('Cache-Control', 'no-cache');
            return fs.createReadStream(foundInDesyImages).pipe(res);
          }
        }
        next();
      });

      middlewares.use(async (req, res, next) => {
        if (req.url === '/') {
          req.url = '/index.html';
        }

        if (req.url.endsWith('.html')) {
          try {
            const templatePath = req.url.slice(1);
            const html = env.render(templatePath);
            res.setHeader('Content-Type', 'text/html');
            res.setHeader('Cache-Control', 'no-cache');
            return res.end(html);
          } catch (e) {
            console.error('Error rendering template:', e.message);
            return next(e);
          }
        }
        next();
      });
    },

    configurePreviewServer(server) {
      const { middlewares } = server;

      env = setupNunjucksEnvironment([
        'src', 
        'src/templates', 
        'node_modules/desy-html/src/templates'
      ], {
        watch: false,
        throwOnUndefined: false
      });

      middlewares.use(async (req, res, next) => {
        if (req.url === '/') {
          req.url = '/index.html';
        }

        if (req.url.endsWith('.html')) {
          try {
            const templatePath = req.url.slice(1);
            const html = env.render(templatePath);
            res.setHeader('Content-Type', 'text/html');
            return res.end(html);
          } catch (e) {
            console.error('Error in preview:', e.message);
            return next(e);
          }
        }
        next();
      });
    },

    transform(content, id) {
      if (id.endsWith('.njk')) {
        const html = env.renderString(content);
        return {
          code: `export default ${JSON.stringify(html)}`,
          map: null
        };
      }
    },

    async buildStart() {
      env = setupNunjucksEnvironment([
        'src', 
        'src/templates', 
        'node_modules/desy-html/src/templates'
      ], {
        watch: false,
        throwOnUndefined: false
      });
    },

    async closeBundle() {
      console.log('🚀 Starting custom build process...');

      await copyAssets();

      await copyBrandingAssets();

      await copyJsLibraries();

      await rewriteCssImagePaths();

      await processNunjucksFiles(env);

      await rewriteHtmlImagePaths();

      await validateBuild();

      console.log('✅ Custom build completed');
    }
  };
}

